"""Official HTTP adapter and independently generated local scenarios.

The controller has no access to scenario truth. Offline outcomes are not official.
"""
import hashlib
import http.client
import json
import math
import time
import http.client
import socket
import time
import uuid
import urllib.parse
import urllib.request
import urllib.error
from pathlib import Path
import numpy as np

def health_check(url,attempts=3,timeout=3.):
    """Opt-in pre-flight TCP reachability check (sends no protocol request)."""
    parsed=urllib.parse.urlparse(url)
    host=parsed.hostname;port=parsed.port or (443 if parsed.scheme=='https' else 80)
    last=None
    for attempt in range(attempts):
        try:
            with socket.create_connection((host,port),timeout=timeout):
                return True
        except OSError as exc:
            last=exc
            if attempt<attempts-1:time.sleep(min(.25*2**attempt,2.))
    raise ConnectionError(f'simulator unreachable at {host}:{port}: {last}')


class HTTPBackend:
    def __init__(self,robot_id,url,log_path):
        self.robot_id=robot_id
        self.url=url.rstrip('/')
        self.virtual_time=0.
        self.log=Path(log_path).open('a',encoding='utf-8')
        self.deadline=time.monotonic()+60
        self.session=uuid.uuid4().hex[:12]
        self.seq=0
        self.opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))

    def post(self,path,payload):
        self.seq+=1
        body={'arena_id':'default','robot_id':self.robot_id,
              'request_id':f'{self.session}-{self.seq}',**payload}
        data=json.dumps(body,ensure_ascii=False,allow_nan=False,separators=(',',':')).encode('utf-8')
        # Retries preserve byte-identical body, request ID and endpoint.
        for attempt in range(6):
            if time.monotonic()>=self.deadline:
                raise TimeoutError('HTTP deadline reached')
            request=urllib.request.Request(self.url+path,data=data,
                         headers={'Content-Type':'application/json; charset=utf-8'},method='POST')
            try:
                with self.opener.open(request,timeout=min(5,max(.1,self.deadline-time.monotonic()))) as response:
                    result=json.load(response)
                self.log.write(json.dumps({'path':path,'request':body,'response':result},ensure_ascii=False)+'\n')
                self.log.flush()
                if result.get('accepted') is not True:
                    raise RuntimeError('Request rejected; check robot_id and simulator state')
                self.virtual_time=float(result['virtual_time_s'])
                return result
            except urllib.error.HTTPError as e:
                # Error replies are not silently turned into new actions.
                self.log.write(json.dumps({'path':path,'request':body,'http_error':e.code})+'\n')
                self.log.flush()
                raise
            except (urllib.error.URLError,TimeoutError,ConnectionError,
                    http.client.IncompleteRead,json.JSONDecodeError) as e:
                self.log.write(json.dumps({'path':path,'request':body,'transport_error':str(e),'attempt':attempt})+'\n')
                self.log.flush()
                if attempt==5:
                    raise
                time.sleep(min(.25*2**attempt,2.))

    def enter(self):
        r=self.post('/enter',{})
        self.deadline=time.monotonic()+r['remaining_real_duration_s']
        return r

    def health(self,attempts=3,timeout=3.):
        return health_check(self.url,attempts=attempts,timeout=timeout)

    def action(self,path,p,c):
        return self.post(path,{'position':{'x':float(p[0]),'y':float(p[1])},'channel':int(c)})

    def exit(self):
        return self.post('/exit',{})

class LocalBackend:
    def __init__(self,seed,problem,error_mode='fixed',radius=None,n=None,all_directional=False):
        rng=np.random.default_rng(seed)
        self.seed=seed
        self.error_mode=error_mode
        count=int(rng.integers(10,17)) if n is None else n
        channels=rng.choice(np.arange(1,21),count,replace=False)
        self.sources={}
        for c in channels:
            r=1800*math.sqrt(float(rng.random())); a=float(rng.uniform(0,2*math.pi))
            self.sources[int(c)]={'p':np.array([r*math.cos(a),r*math.sin(a)]),
                'radius':float(rng.uniform(1000,1500)) if radius is None else radius,
                'direction':float(rng.uniform(0,2*math.pi)) if problem==4 and (all_directional or rng.random()<.5) else None,
                'alive':True}
        self.pos=np.zeros(2); self.channel=1; self.virtual_time=0.; self.trace=[]
        self.parts={'move_s':0.,'switch_s':0.,'measure_s':0.,'optical_s':0.,'laser_s':0.}

    def enter(self):
        return {'accepted':True,'remaining_real_duration_s':1200,'virtual_time_s':0.}

    def error(self,p,c):
        if self.error_mode=='plus':
            return 1.
        if self.error_mode=='minus':
            return -1.
        # Deterministic by position/channel: no fresh noise on repeated readings.
        text=f'{self.seed}:{c}:{p[0]:.8f}:{p[1]:.8f}'.encode()
        h=int.from_bytes(hashlib.sha256(text).digest()[:8],'big')
        return 2*h/(2**64-1)-1

    def action(self,path,p,c):
        p=np.asarray(p,dtype=float)
        move=float(np.linalg.norm(p-self.pos))/5
        self.parts['move_s']+=move
        self.virtual_time+=move
        self.pos=p.copy()
        s=self.sources.get(c)
        distance=float(np.linalg.norm(p-s['p'])) if s else float('inf')
        result={'accepted':True}
        if path=='/measure':
            switch=int(self.channel!=c)
            self.parts['switch_s']+=switch; self.parts['measure_s']+=5
            self.virtual_time+=5+switch
            self.channel=c
            visible=bool(s and s['alive'] and distance<=s['radius'])
            if visible and s['direction'] is not None:
                v=np.array([math.cos(s['direction']),math.sin(s['direction'])])
                visible=float((p-s['p'])@v)>=-1e-9
            if not visible:
                result['measure_result']='no_signal'
            elif distance<=5:
                result['measure_result']='near'
            else:
                result['measure_result']='direction'
                delta=s['p']-p
                angle=(math.degrees(math.atan2(delta[1],delta[0]))+self.error(p,c))%360
                result['svd_deg']=round(angle,2)%360
        else:
            self.parts['optical_s']+=3; self.virtual_time+=3
            success=bool(s and s['alive'] and distance<=20)
            result['clear_result']='success' if success else 'no_target_in_range'
            if success:
                s['alive']=False
                self.parts['laser_s']+=2; self.virtual_time+=2
        result['virtual_time_s']=self.virtual_time
        self.trace.append({'path':path,'p':p.tolist(),'channel':int(c),'result':result.copy()})
        if self.virtual_time>=360000:
            raise TimeoutError('Virtual time limit')
        return result

    def exit(self):
        return {'accepted':True,'virtual_time_s':self.virtual_time,'exit_reason':'user_exit'}

batch_evaluation.py.source:
"""Batch seed evaluation of the current default policy.

Arms
----
Problem 3:
  default   OmniSearchSolver (team baseline, negative observations off)
  negative  default + negative_observations=True
Problem 4:
  default   JointSearchSolver (16-upper-bound discovery closure on)
  noclosure default + close_discovery_on_upper_bound=False   (A/B control)
  step      default + reschedule_after_step=True             (reference only)

Reports the full per-arm distribution (mean, sd, P50/P90/P95/P99, CVaR95 = mean
of the worst 5%, max) plus completion diagnostics and paired ratios against the
reference arm. Output CSV is append-only and resumable: already recorded
(seed, arm) pairs are skipped, so a long batch can be run in chunks.
"""
import argparse
import csv
import json
import math
import statistics
import time
from pathlib import Path

from backend import LocalBackend
from audit import AuditPort

ROOT = Path(__file__).resolve().parent
ARMS = {3: ('default', 'negative'), 4: ('default', 'noclosure', 'step')}
REFERENCE = {3: 'default', 4: 'default'}


def make_solver(port, problem, arm):
    if problem == 3:
        from omni_search import OmniSearchSolver
        if arm == 'default':
            return OmniSearchSolver(port, 3)
        if arm == 'negative':
            return OmniSearchSolver(port, 3, negative_observations=True)
    else:
        from joint_search import JointSearchSolver
        if arm == 'default':
            return JointSearchSolver(port, 4)
        if arm == 'noclosure':
            return JointSearchSolver(port, 4, close_discovery_on_upper_bound=False)
        if arm == 'step':
            return JointSearchSolver(port, 4, reschedule_after_step=True)
    raise ValueError(f'Unknown arm {arm!r} for problem {problem}')


def run_one(seed, problem, arm):
    backend = LocalBackend(seed, problem)
    port = AuditPort(backend)
    started = time.perf_counter()
    result = make_solver(port, problem, arm).run()
    result.update(seed=seed, problem=problem, arm=arm,
                  normal_exit=port.exited, sources=len(backend.sources),
                  wall_s=time.perf_counter() - started)
    if result['cleared'] != len(backend.sources) or not port.exited:
        raise RuntimeError(f'arm={arm} seed={seed}: incomplete run')
    return result


def percentile(values, fraction):
    if not values:
        return None
    ordered = sorted(values)
    return ordered[min(len(ordered) - 1, int(math.ceil(fraction * len(ordered))) - 1)]


def dist(values):
    if not values:
        return {}
    ordered = sorted(values)
    tail = ordered[max(0, len(ordered) - max(1, int(math.ceil(0.05 * len(ordered))))):]
    return {'n': len(values),
            'mean': statistics.fmean(values),
            'sd': statistics.stdev(values) if len(values) > 1 else 0.,
            'min': ordered[0], 'p50': percentile(values, .5), 'p90': percentile(values, .9),
            'p95': percentile(values, .95), 'p99': percentile(values, .99),
            'cvar95': statistics.fmean(tail), 'max': ordered[-1]}


def summarize(rows, problem):
    arms = ARMS[problem]
    by_arm = {arm: [r for r in rows if r['arm'] == arm] for arm in arms}
    out = {'problem': problem, 'reference': REFERENCE[problem], 'arms': {}}
    for arm, rs in by_arm.items():
        if not rs:
            continue
        means = [r['mean_time_s'] for r in rs]
        out['arms'][arm] = {
            'distribution_mean_time_s': dist(means),
            'mean_total_virtual_time_s': statistics.fmean([r['virtual_time_s'] for r in rs]),
            'sources_total': sum(r['sources'] for r in rs),
            'fallbacks': sum(r['fallback'] for r in rs),
            'failed_clear': sum(r['failed_clear'] for r in rs),
            'measurements': sum(r['measure'] for r in rs),
            'under_400_seeds': sum(1 for x in means if x <= 400),
        }
        if problem == 4:
            out['arms'][arm]['under_400_rate'] = (
                out['arms'][arm]['under_400_seeds'] / len(rs))
    ref = {r['seed']: r for r in by_arm.get(REFERENCE[problem], [])}
    for arm, rs in by_arm.items():
        if arm == REFERENCE[problem] or not ref:
            continue
        paired = [(r, r['mean_time_s'] / ref[r['seed']]['mean_time_s'])
                  for r in rs if r['seed'] in ref]
        if not paired:
            continue
        ratios = [ratio for _, ratio in paired]
        out['arms'][arm]['paired'] = {
            'mean_ratio': statistics.fmean(ratios),
            'median_ratio': statistics.median(ratios),
            'worst_ratio': max(ratios),
            'worst_seed': max(paired, key=lambda p: p[1])[0]['seed'],
            'better': sum(1 for x in ratios if x < 1 - 1e-12),
            'equal': sum(1 for x in ratios if abs(x - 1) <= 1e-12),
            'worse': sum(1 for x in ratios if x > 1 + 1e-12),
            'over_5pct': [{'seed': r['seed'], 'ratio': ratio}
                          for r, ratio in paired if ratio > 1.05],
        }
    return out


def main():
    ap = argparse.ArgumentParser(description='Batch seed evaluation')
    ap.add_argument('--problem', type=int, choices=[3, 4], required=True)
    ap.add_argument('--start', type=int, required=True)
    ap.add_argument('--count', type=int, default=40)
    ap.add_argument('--arms', nargs='+', default=None)
    ap.add_argument('--output', default=None)
    ap.add_argument('--summary-only', action='store_true')
    a = ap.parse_args()

    arms = a.arms or list(ARMS[a.problem])
    out = Path(a.output) if a.output else ROOT / 'results' / 'batch'
    out.mkdir(parents=True, exist_ok=True)
    metrics = out / f'q{a.problem}_metrics.csv'
    summary_path = out / f'q{a.problem}_summary.json'

    rows, done = [], set()
    if metrics.exists():
        with metrics.open(encoding='utf-8-sig') as f:
            rows = [dict(r) for r in csv.DictReader(f)]
        done = {(int(r['seed']), r['arm']) for r in rows}
        for r in rows:
            for key in ('seed', 'problem', 'sources'):
                r[key] = int(r[key])
            for key in r:
                if key not in ('seed', 'arm', 'problem', 'sources', 'normal_exit'):
                    try:
                        r[key] = float(r[key])
                    except ValueError:
                        pass

    if not a.summary_only:
        seeds = list(range(a.start, a.start + a.count))
        for seed in seeds:
            for arm in arms:
                if (seed, arm) in done:
                    continue
                result = run_one(seed, a.problem, arm)
                rows.append(result)
                print(f'q{a.problem} seed={seed} arm={arm:9s} sources={result["sources"]:2d} '
                      f'mean={result["mean_time_s"]:8.3f}s total={result["virtual_time_s"]:9.1f}s '
                      f'fb={result["fallback"]} failed={result["failed_clear"]} '
                      f'wall={result["wall_s"]:.1f}s', flush=True)
        fields = sorted({k for r in rows for k in r})
        with metrics.open('w', newline='', encoding='utf-8-sig') as f:
            w = csv.DictWriter(f, fieldnames=fields)
            w.writeheader()
            w.writerows(rows)

    summary = summarize([r for r in rows if r['arm'] in arms], a.problem)
    summary['seeds'] = sorted({r['seed'] for r in rows})
    summary_path.write_text(json.dumps(summary, indent=2), encoding='utf-8')
    print(json.dumps(summary, indent=2))


if __name__ == '__main__':
    main()

geometry.py.source:
"""Conservative bearing geometry. Coordinates metres, angles degrees."""
import math
import itertools
import numpy as np

EPS_DEG = 1.005001  # 1 degree physical error plus 0.005 degree rounding

def unit(deg):
    a = math.radians(deg)
    return np.array([math.cos(a), math.sin(a)])

def clip(poly, normal, bound):
    """Clip convex polygon by normal @ x <= bound, retaining boundary."""
    if len(poly) == 0:
        return np.empty((0, 2))
    out = []
    prev = poly[-1]
    fp = float(np.dot(normal, prev) - bound)
    for cur in poly:
        fc = float(np.dot(normal, cur) - bound)
        if (fp <= 1e-8) != (fc <= 1e-8):
            out.append(prev + fp / (fp - fc) * (cur - prev))
        if fc <= 1e-8:
            out.append(cur)
        prev, fp = cur, fc
    if not out:
        return np.empty((0, 2))
    clean = [out[0]]
    for p in out[1:]:
        if np.linalg.norm(p-clean[-1]) > 1e-7:
            clean.append(p)
    if len(clean)>1 and np.linalg.norm(clean[0]-clean[-1])<1e-7:
        clean.pop()
    return np.asarray(clean)

def bearing_clip(poly, position, angle, error=EPS_DEG):
    p = np.asarray(position, dtype=float)
    lo, hi = unit(angle-error), unit(angle+error)
    # cross(lo, x-p)>=0 and cross(hi,x-p)<=0
    for n in (np.array([lo[1], -lo[0]]), np.array([-hi[1], hi[0]])):
        poly = clip(poly, n, float(n @ p))
    return poly

def feasible(observations, error=EPS_DEG):
    """Outer polygon, never an inscribed approximation of a physical disk."""
    poly = np.array([[-1800.,-1800.],[1800.,-1800.],[1800.,1800.],[-1800.,1800.]])
    for deg in np.arange(0.,360.,11.25):
        poly = clip(poly, unit(deg), 1800.)
    for p, angle in observations:
        poly = bearing_clip(poly, p, angle, error)
        for deg in np.arange(0.,360.,22.5):
            n = unit(deg)
            poly = clip(poly,n,float(n@p)+1500.)
    return poly

def diameter(poly):
    if len(poly)==0:
        raise ValueError('Empty region has no localization diameter')
    delta = poly[:,None,:]-poly[None,:,:]
    d2 = (delta*delta).sum(axis=2)
    i,j = np.unravel_index(np.argmax(d2), d2.shape)
    return math.sqrt(float(d2[i,j])), (poly[i],poly[j])

def region_from_bearings(observations,error=1.):
    """Q1 only: exact wedge intersection, with empty/unbounded classification.

    No artificial bounding square or reception disk is added in this function.
    Pair enumeration O(n^3); diameter over finite vertices O(v^2).
    """
    if not observations:
        return {'status':'unbounded','diameter':float('inf'),'vertices':np.empty((0,2))}
    normals=[];bounds=[]
    for p,angle in observations:
        p=np.asarray(p)
        lo,hi=unit(angle-error),unit(angle+error)
        for n in (np.array([lo[1],-lo[0]]),np.array([-hi[1],hi[0]])):
            normals.append(n);bounds.append(float(n@p))
    A=np.array(normals);b=np.array(bounds)
    vertices=[]
    for i,j in itertools.combinations(range(len(A)),2):
        mat=A[[i,j]]
        if abs(np.linalg.det(mat))<1e-12:
            continue
        p=np.linalg.solve(mat,b[[i,j]])
        if np.all(A@p<=b+1e-7) and all(np.linalg.norm(p-q)>1e-6 for q in vertices):
            vertices.append(p)
    if not vertices:
        return {'status':'empty','diameter':None,'vertices':np.empty((0,2))}
    for n in A:
        for d in (np.array([-n[1],n[0]]),np.array([n[1],-n[0]])):
            if np.all(A@d<=1e-10):
                return {'status':'unbounded','diameter':float('inf'),'vertices':np.array(vertices)}
    vertices=np.array(vertices)
    center=vertices.mean(axis=0)
    order=np.argsort(np.arctan2(vertices[:,1]-center[1],vertices[:,0]-center[0]))
    vertices=vertices[order]
    return {'status':'bounded','diameter':diameter(vertices)[0],'vertices':vertices}

def enclosing_circle(poly):
    """Exact candidate enumeration; final radius recomputed over every vertex."""
    if not len(poly):
        raise ValueError('Inconsistent or empty bearing intersection')
    best_c = np.mean(poly,axis=0)
    best_r = float(np.max(np.linalg.norm(poly-best_c,axis=1)))
    def consider(c):
        nonlocal best_c,best_r
        r = float(np.max(np.linalg.norm(poly-c,axis=1)))
        if r < best_r:
            best_c,best_r=c,r
    for p in poly:
        consider(p)
    for a,b in itertools.combinations(poly,2):
        consider((a+b)/2)
    for a,b,c in itertools.combinations(poly,3):
        mat = 2*np.array([b-a,c-a])
        if abs(np.linalg.det(mat))<1e-9:
            continue
        center = a+np.linalg.solve(mat,np.array([np.dot(b-a,b-a),np.dot(c-a,c-a)]))
        consider(center)
    return best_c,best_r

def optical_cover(poly, angle):
    """Cover enclosing rotated rectangle by cells of side <=27, radius <20."""
    u=unit(angle); v=np.array([-u[1],u[0]])
    axes=np.array([u,v])
    q=poly@axes.T
    lo=q.min(axis=0); hi=q.max(axis=0)
    counts=np.maximum(1,np.ceil((hi-lo)/27.).astype(int))
    step=(hi-lo)/counts
    out=[]
    # snake along long dimension; only <=2-3 rows for a single bearing cone
    for j in range(counts[1]):
        ix=range(counts[0]) if j%2==0 else range(counts[0]-1,-1,-1)
        for i in ix:
            out.append((lo+step*np.array([i+.5,j+.5]))@axes)
    return np.asarray(out)

def distance_origin_triangle(t):
    crosses=[]
    for i in range(3):
        a=t[(i+1)%3]-t[i]; b=-t[i]
        crosses.append(float(a[0]*b[1]-a[1]*b[0]))
    if min(crosses)>=-1e-9 or max(crosses)<=1e-9:
        return 0.
    ds=[]
    for a,b in zip(t,np.roll(t,-1,axis=0)):
        d=b-a
        s=np.clip(-float(a@d)/float(d@d),0,1)
        ds.append(np.linalg.norm(a+s*d))
    return float(min(ds))

def search_stations(problem, spacing=950., layout='original'):
    if layout not in ('original','compact','radial','rings'):
        raise ValueError('Unknown coverage layout')
    if layout=='rings':
        if problem!=4 or spacing!=950.:
            raise ValueError('Certified ring coverage requires Q4 and default spacing')
        # 22 sites. Continuous square subdivision certifies that every source
        # is in the convex hull of receivable-distance sites; triangle edge
        # lengths alone are not sufficient to verify this smaller layout.
        a=np.arange(7)*2*np.pi/7;b=np.arange(14)*np.pi/7
        return np.vstack([np.zeros((1,2)),999.*np.column_stack([np.cos(a),np.sin(a)]),
                          1870.*np.column_stack([np.cos(b),np.sin(b)])])
    if layout=='compact' and (problem!=4 or spacing!=950.):
        raise ValueError('Compact boundary coverage is verified only for Q4, spacing 950m')
    if layout=='radial':
        if problem!=4 or spacing!=950.:
            raise ValueError('Radial coverage is verified only for Q4, spacing 950m')
        original=search_stations(4,spacing,layout='original')
        inner=original[np.linalg.norm(original,axis=1)<2000]
        # Collapse each pair of distant vertices into one boundary vertex.
        # The resulting 36 triangles have edges <=983.513m and positive area.
        # Their regular 12-gon boundary has inradius 1835.259m >1800m.
        boundary=np.array([[1900*math.cos(math.radians(30+60*k)),
                            1900*math.sin(math.radians(30+60*k))] for k in range(6)])
        return np.vstack([inner,boundary])
    if problem==3:
        radius=1800*math.cos(math.pi/6)
        return np.array([[0.,0.]]+[list(radius*unit(60*k)) for k in range(6)])
    if not 0<spacing<=1000:
        raise ValueError('Directional coverage requires 0 < spacing <= 1000')
    a=np.array([spacing,0.]); b=np.array([spacing/2,spacing*math.sqrt(3)/2])
    k=math.ceil(2*1800/spacing)+3
    vertices=set()
    for i in range(-k,k+1):
        for j in range(-k,k+1):
            base=i*a+j*b
            for offsets in ([np.zeros(2),a,b],[a,b,a+b]):
                t=np.array([base+z for z in offsets])
                if distance_origin_triangle(t)<=1800+1e-8:
                    vertices.update(tuple(np.round(p,9)) for p in t)
    points=np.array(sorted(vertices))
    if layout=='compact':
        # Keep triangle connectivity and all 13 interior stations unchanged.
        # The 42 deformed triangles keep positive orientation and edges <=1000m;
        # their simple outer boundary stays outside the radius-1800m disk.
        # Thus each target remains enclosed by three receivable-distance sites,
        # at least one of which lies in any transmitting closed half-plane.
        distances=np.linalg.norm(points,axis=1)
        far=distances>2000.
        points[far]*=(1950./distances[far])[:,None]
    return points

